import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Stall from "./components/stall"; // Import the 3D Stall component

const WebApp = () => {
    const [darkMode, setDarkMode] = useState(false);

    const services = [
        { title: "Floor Planning", desc: "Strategic space management for maximum flow.", icon: "📐" },
        { title: "Vendor Sourcing", desc: "Connecting you with top-tier booth builders.", icon: "🤝" },
        { title: "Digital Integration", desc: "Hybrid event solutions and custom event apps.", icon: "🌐" },
    ];

    return (
        <div className={`${darkMode ? "bg-gray-900 text-white" : "bg-gray-50 text-gray-900"} min-h-screen transition-colors duration-500 font-sans`}>

            {/* --- Floating Navigation --- */}
            <nav className={`fixed w-full z- px-8 py-4 flex justify-between items-center backdrop-blur-md ${darkMode ? "bg-gray-900/80" : "bg-white/80"} border-b border-gray-200/20`}>
                <motion.h1
                    initial={{ x: -20, opacity: 0 }}
                    animate={{ x: 0, opacity: 1 }}
                    className="text-2xl font-black tracking-tighter text-blue-500"
                >
                    VANTAGE
                </motion.h1>

                <div className="flex items-center gap-6">
                    <button
                        onClick={() => setDarkMode(!darkMode)}
                        className="p-2 rounded-full bg-gray-200 dark:bg-gray-700 hover:scale-110 transition"
                    >
                        {darkMode ? "☀️" : "🌙"}
                    </button>
                    <button className="bg-blue-600 text-white px-6 py-2 rounded-full font-bold hover:shadow-lg hover:shadow-blue-500/50 transition-all">
                        Get Started
                    </button>
                </div>
            </nav>

            {/* --- 3D Stall Section (Integrated at Top) --- */}
            <section className="relative w-full h-[600px] overflow-hidden shadow-2xl">
                <Stall />
                {/* Overlay gradient to blend 3D stall into the Hero section */}
                <div className={`absolute bottom-0 w-full h-32 bg-gradient-to-t ${darkMode ? 'from-gray-900' : 'from-gray-50'} to-transparent pointer-events-none`} />
            </section>

            {/* --- Interactive Hero --- */}
            <header className="relative pt-20 pb-20 px-8 overflow-hidden">
                <motion.div
                    initial={{ y: 50, opacity: 0 }}
                    whileInView={{ y: 0, opacity: 1 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.8 }}
                    className="relative z-10 text-center"
                >
                    <span className="text-blue-500 font-bold tracking-widest uppercase text-sm">Beyond Boundaries</span>
                    <h2 className="text-6xl md:text-8xl font-extrabold mt-4 mb-6 tracking-tight">
                        Design. <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-600">Build.</span> Scale.
                    </h2>
                    <p className="text-xl opacity-70 max-w-xl mx-auto mb-8">
                        The next generation of exhibition organizing. We don't just host events; we build immersive ecosystems.
                    </p>
                </motion.div>

                <motion.div
                    animate={{ rotate: 360 }}
                    transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
                    className="absolute -top-20 -right-20 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl"
                />
            </header>

            {/* --- Hover-Effect Services --- */}
            <section className="py-20 px-8 max-w-7xl mx-auto">
                <div className="grid md:grid-cols-3 gap-8">
                    {services.map((service, index) => (
                        <motion.div
                            key={index}
                            whileHover={{ y: -10 }}
                            className={`p-10 rounded-3xl border ${darkMode ? "bg-gray-800 border-gray-700" : "bg-white border-gray-100"} shadow-2xl transition-all group`}
                        >
                            <div className="text-4xl mb-4 group-hover:scale-125 transition-transform inline-block">
                                {service.icon}
                            </div>
                            <h4 className="text-2xl font-bold mb-3">{service.title}</h4>
                            <p className="opacity-60 leading-relaxed">{service.desc}</p>
                            <motion.div
                                className="mt-6 h-1 w-0 bg-blue-500 group-hover:w-full transition-all duration-500"
                            />
                        </motion.div>
                    ))}
                </div>
            </section>

            {/* --- Stats Counter (Visual) --- */}
            <section className={`py-16 ${darkMode ? "bg-gray-800/50" : "bg-blue-600"} text-white text-center`}>
                <div className="grid md:grid-cols-3 gap-10 max-w-5xl mx-auto">
                    <div>
                        <div className="text-5xl font-black">500+</div>
                        <div className="opacity-70">Events Managed</div>
                    </div>
                    <div>
                        <div className="text-5xl font-black">12M+</div>
                        <div className="opacity-70">Attendees Yearly</div>
                    </div>
                    <div>
                        <div className="text-5xl font-black">Global</div>
                        <div className="opacity-70">24 Country Reach</div>
                    </div>
                </div>
            </section>

            {/* --- Footer --- */}
            <footer className="py-12 text-center opacity-50 text-sm">
                <p>© 2026 VANTAGE EXHIBITS. ARCHITECTING THE FUTURE OF CONNECTION.</p>
            </footer>
        </div>
    );
};

export default WebApp;
